#!/usr/bin/env bash
# batch_p06b_redis_cache_fix.sh
#
# Fixes the real, VPS-confirmed failure from batch_p06b_killswitch.sh's first
# run: all 10 killswitch.test.js tests failed with
#   Error: connect ECONNREFUSED 127.0.0.1:6379
# Root cause (confirmed, not guessed - see docs/P0_DEVIATIONS.md D-26 and
# docs/P0_FINDINGS.md F12): this VPS's docker-compose.yml has NO separate
# redis-cache service, so the real gateway test container's environment
# never sets REDIS_CACHE_HOST/PORT - config.js falls back to its
# 127.0.0.1:6379 default, which does not resolve to anything inside the
# container's network on the VPS (unlike the local sandbox, where 127.0.0.1
# really is where a local redis-server was running).
#
# NO SOURCE CODE CHANGED - killswitch.js itself is correct (10/10 passed
# locally once pointed at a real, reachable Redis). This script only:
#   1. Updates docs/P0_DEVIATIONS.md (adds D-26) and docs/P0_FINDINGS.md
#      (adds F12) with the real finding above.
#   2. Re-runs the test suite with the test command's `docker compose run`
#      explicitly pointed at the ALREADY-RUNNING redis-durable container
#      (-e REDIS_CACHE_HOST=redis-durable -e REDIS_CACHE_PORT=6379) as a
#      temporary stand-in for redis-cache, for verification purposes only -
#      NOT a claim about how the real running gateway process should be
#      wired in production. `ks:*` keys are a disjoint namespace from
#      redis-durable's own out:*/in:*/etc keys, so this is safe.
#
# Still does NOT run `git add`/`git commit`.
#
# OPEN QUESTION for you (D-26, real - not something I can resolve myself
# without seeing this VPS's actual docker-compose.yml): should a genuine
# separate `redis-cache` service be added to docker-compose.yml (matching
# the architecture spec literally), or is sharing redis-durable permanently
# fine here? Either way, wiring the REAL running gateway container's
# REDIS_CACHE_HOST/PORT (not just this test command) requires editing
# docker-compose.yml itself - please paste its `gateway`/`redis-durable`
# service blocks (or the whole file) so that edit can be made precisely
# instead of guessed at.
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -euo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
if [ ! -d "$REPO_ROOT/gateway" ]; then
  echo "ERROR: $REPO_ROOT/gateway not found. Run this script from a machine where the repo lives at $REPO_ROOT, or edit REPO_ROOT at the top of this script." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "=== [0/4] Pre-flight: repo root = $REPO_ROOT ==="
git rev-parse --is-inside-work-tree >/dev/null 2>&1 && echo "  git repo: OK" || { echo "ERROR: not a git repository" >&2; exit 1; }

echo ""
echo "=== [1/4] Writing docs (base64-embedded, decoded in place) ==="

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

