echo ""
echo "=== [2/4] Full real-Redis test suite, this time with REDIS_CACHE_HOST/PORT explicitly pointed at redis-durable ==="
if ! command -v docker >/dev/null 2>&1; then
  echo "ERROR: docker not found - cannot run the real-Redis test suite." >&2
  exit 1
fi
DC="docker compose"
$DC version >/dev/null 2>&1 || DC="docker-compose"

$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -e LOG_LEVEL=error \
  -e METRICS_TOKEN=test-token \
  -e REDIS_CACHE_HOST=redis-durable \
  -e REDIS_CACHE_PORT=6379 \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/scripts:/app/scripts:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  -v "$(pwd)/gateway/package.json:/app/package.json:ro" \
  gateway npm test

echo ""
echo "=== [3/4] Confirm the redis-durable container's real compose service name ==="
echo "  This script assumed the compose service name is exactly 'redis-durable' (matches the"
echo "  'sharwa_ai-redis-durable-1' container name seen in your earlier output). If step [2/4]"
echo "  above still shows ECONNREFUSED, the service name may differ - please paste"
echo "  'docker compose ps' or the redis-durable service block from docker-compose.yml."

echo ""
echo "=== [4/4] Review: git status / diff --stat (NO commit performed by this script) ==="
git status --short
echo ""
git diff --stat -- docs/P0_DEVIATIONS.md docs/P0_FINDINGS.md || true

echo ""
echo "=== Done. Nothing was committed. ==="
echo "If [2/4] shows 116/116 passing this time, please also paste docker-compose.yml's"
echo "gateway/redis-durable service blocks (or the whole file) plus your decision on D-26"
echo "(dedicated redis-cache service vs. permanently sharing redis-durable), so the real"
echo "docker-compose.yml wiring for the actual running gateway process can be done next -"
echo "then I will prepare batch_p06b_commit.sh."
